def receive(self, amount: int) -> int:
    if amount < 0:
        raise ValueError("negative damage")
    # Poison bypasses shield, direct damage consumes shield first
    is_poison = "poison" in self.statuses
    if is_poison:
        dealt = min(self.hp, amount)
        self.hp -= dealt
    else:
        shield_dealt = min(self.shield, amount)
        self.shield -= shield_dealt
        remaining = amount - shield_dealt
        if remaining > 0:
            dealt = min(self.hp, remaining)
            self.hp -= dealt
        else:
            dealt = 0
    # Designer decision R2.2: poison must never reduce HP below 1
    if is_poison and self.hp < 1:
        self.hp = 1
    self.alive = self.hp > 0
    return dealt

